program='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != bg and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            components.append(comp)
    if not components:
        return [row[:] for row in grid]
    sprite = max(components, key=len)
    r0 = min(r for r,c in sprite); r1 = max(r for r,c in sprite)
    c0 = min(c for r,c in sprite); c1 = max(c for r,c in sprite)
    ph, pw = r1-r0+1, c1-c0+1
    pattern = [grid[r0+i][c0:c1+1] for i in range(ph)]
    out = [row[:] for row in grid]
    # Every separate non-background component marks the center of another copy.
    for comp in components:
        if comp is sprite:
            continue
        for r, c in comp:
            top, left = r-ph//2, c-pw//2
            for i in range(ph):
                for j in range(pw):
                    rr, cc = top+i, left+j
                    if 0 <= rr < h and 0 <= cc < w and pattern[i][j] != bg:
                        out[rr][cc] = pattern[i][j]
    return out
'''
