def parse_demo(text, n):
    def section(kind):
        pat=rf'Demo pair {n} {kind} \(\d+x\d+\):\n((?:[0-9 ]+\n)+)'
        m=re.search(pat,text)
        if not m: raise ValueError((kind, text[:100]))
        return [[int(x) for x in line.split()] for line in m.group(1).strip().splitlines()]
    return section('input'), section('output')
